        coordinator: 'Coordinación de Mecanización Agrícola',
        code: 'MAG-ISTAE'
      }
    };

    const SECRETARIA_GENERAL_EMAIL = 'secretariageneralistae@gmail.com';
    const SECRETARIA_WHATSAPP = '593996566160';

    // Control de Navbar Sticky y Scroll
    window.addEventListener('scroll', () => {
      const navbar = document.getElementById('mainNavbar');
      if (navbar) {
        if (window.scrollY > 20) {
          navbar.classList.add('is-scrolled');
        } else {
          navbar.classList.remove('is-scrolled');
        }
      }
    });

    // Control de Menú Móvil
    function toggleMobileMenu() {
      const menu = document.getElementById('navMenuWrapper');
      if (menu) {
        menu.classList.toggle('active');
      }
    }

    // Control de Dropdowns en Móvil
    function toggleDropdown(el) {
      if (window.innerWidth <= 1140) {
        const item = el.closest('.nav-item');
        if (item) {
          item.classList.toggle('mobile-open');
        }
      }
    }

    // Cerrar menú móvil al hacer clic en un enlace
    document.querySelectorAll('.dropdown-link, .nav-link').forEach(link => {
      link.addEventListener('click', () => {
        if (window.innerWidth <= 1140 && !link.parentElement.classList.contains('has-dropdown')) {
          const menu = document.getElementById('navMenuWrapper');
          if (menu) menu.classList.remove('active');
        }
      });
    });

    // Control Acordeón FAQ Interactivo
    document.querySelectorAll('.faq-toggle-btn').forEach(trigger => {
      trigger.addEventListener('click', () => {
        const parent = trigger.parentElement;
        const isActive = parent.classList.contains('active');
        
        document.querySelectorAll('.faq-card-item').forEach(item => {
          item.classList.remove('active');
        });

        if (!isActive) {
          parent.classList.add('active');
        }
      });
    });

    // Actualizar indicador visual del correo institucional al seleccionar carrera
    function updateCareerEmailNotice(careerName) {
      const targetInfo = document.getElementById('careerTargetInfo');
      const targetText = document.getElementById('careerEmailText');
      
      if (!targetInfo || !targetText) return;

      if (careerName && CAREER_EMAILS[careerName]) {
        targetText.textContent = CAREER_EMAILS[careerName].email;
        targetInfo.style.display = 'block';
      } else {
        targetInfo.style.display = 'none';
      }
    }

    // Control Modal de Postulación
    function openAdmissionModal(careerName = '') {
      const modal = document.getElementById('admissionModal');
      const form = document.getElementById('admissionForm');
      const success = document.getElementById('successMessage');
      const select = document.getElementById('careerSelect');
      
      form.style.display = 'block';
      success.style.display = 'none';

      if (careerName && select) {
        select.value = careerName;
        updateCareerEmailNotice(careerName);
      } else if (select) {
        updateCareerEmailNotice(select.value);
      }

      modal.classList.add('active');
      document.body.style.overflow = 'hidden';
    }

    function closeAdmissionModal() {
      const modal = document.getElementById('admissionModal');
      modal.classList.remove('active');
      document.body.style.overflow = 'auto';
    }

    function resetAndNewAdmission() {
      const form = document.getElementById('admissionForm');
      const success = document.getElementById('successMessage');
      const targetInfo = document.getElementById('careerTargetInfo');
      
      if (form) form.reset();
      if (targetInfo) targetInfo.style.display = 'none';
      if (form) form.style.display = 'block';
      if (success) success.style.display = 'none';
    }

    // Cerrar al hacer clic fuera del modal
    window.addEventListener('click', (e) => {
      const modal = document.getElementById('admissionModal');
      if (e.target === modal) {
        closeAdmissionModal();
      }
    });

    // Cerrar con tecla Escape
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        closeAdmissionModal();
      }
    });

    // Smooth scroll automático para todos los enlaces internos (#)
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
      anchor.addEventListener('click', function(e) {
        const targetId = this.getAttribute('href');
        if (targetId && targetId !== '#' && targetId.startsWith('#')) {
          const targetElement = document.querySelector(targetId);
          if (targetElement) {
            e.preventDefault();
            targetElement.scrollIntoView({
              behavior: 'smooth',
              block: 'start'
            });
            if (history.pushState) {
              history.pushState(null, null, targetId);
            }
          }
        }
      });
    });

    // Procesar envío de nuevo aspirante y remitir al correo institucional de la carrera
    async function handleFormSubmit(e) {
      e.preventDefault();
      
      const form = document.getElementById('admissionForm');
      const success = document.getElementById('successMessage');
      const submitBtn = document.getElementById('submitAdmissionBtn');
      const btnText = submitBtn.querySelector('.btn-submit-text');
      const btnLoader = submitBtn.querySelector('.btn-submit-loader');

      const fullName = document.getElementById('fullName').value.trim();
      const cedula = document.getElementById('cedula').value.trim();
      const phone = document.getElementById('phone').value.trim();
      const email = document.getElementById('email').value.trim();
      const career = document.getElementById('careerSelect').value;

      const careerData = CAREER_EMAILS[career] || {
        email: 'secretariageneralistae@gmail.com',
        coordinator: 'Secretaría General ISTAE',
        code: 'ISTAE'
      };
      const careerEmail = careerData.email;

      // Estado de carga visual en el botón
      submitBtn.disabled = true;
      if (btnText) btnText.style.display = 'none';
      if (btnLoader) btnLoader.style.display = 'inline-flex';

      const registrationDate = new Date().toLocaleString('es-EC', {
        timeZone: 'America/Guayaquil',
        dateStyle: 'full',
        timeStyle: 'medium'
      });

      // Preparar payload de envío por correo (FormSubmit API)
      const payload = {
        _subject: `[ISTAE Admisión] Nuevo Aspirante: ${fullName} - ${career}`,
        _cc: SECRETARIA_GENERAL_EMAIL,
        _replyto: email,
        _template: 'table',
        'Nombres y Apellidos': fullName,
        'Cédula o Pasaporte': cedula,
        'Teléfono o WhatsApp': phone,
        'Correo del Aspirante': email,
        'Carrera Postulada': career,
        'Correo Institucional Destino': careerEmail,
        'Fecha y Hora de Registro': registrationDate,
        'Institución': 'Instituto Superior Tecnológico Alberto Enríquez (ISTAE)'
      };

      try {
        // Envío asíncrono al correo institucional de la carrera
        fetch(`https://formsubmit.co/ajax/${careerEmail}`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json'
          },
          body: JSON.stringify(payload)
        }).catch(err => {
          console.log('Notificación en segundo plano procesada:', err);
        });
      } catch (err) {
        console.error('Error de red al notificar correo institucional:', err);
      }

      // Configurar enlace mailto estructurado con la plantilla oficial
      const mailtoSubject = encodeURIComponent(`[ISTAE Admisión] Postulación de Aspirante - ${fullName} - ${career}`);
      const mailtoBody = encodeURIComponent(
        `NOTIFICACIÓN DE INGRESO DE NUEVO ASPIRANTE - ISTAE\n` +
        `====================================================\n\n` +
        `Para: ${careerData.coordinator} (${careerEmail})\n` +
        `Con copia a: Secretaría General (${SECRETARIA_GENERAL_EMAIL})\n\n` +
        `DATOS DEL NUEVO ASPIRANTE:\n` +
        `----------------------------------------------------\n` +
        `• Nombres y Apellidos : ${fullName}\n` +
        `• Cédula / Pasaporte  : ${cedula}\n` +
        `• Teléfono / WhatsApp : ${phone}\n` +
        `• Correo Electrónico  : ${email}\n` +
        `• Carrera de Elección : ${career}\n` +
        `• Correo Institucional: ${careerEmail}\n` +
        `• Fecha de Registro   : ${registrationDate}\n\n` +
        `----------------------------------------------------\n` +
        `Sistema Oficial de Admisión y Registro\n` +
        `Instituto Superior Tecnológico Alberto Enríquez (ISTAE)\n` +
        `San Lorenzo - Esmeraldas, Ecuador`
      );
      
      const mailtoUrl = `mailto:${careerEmail}?cc=${encodeURIComponent(SECRETARIA_GENERAL_EMAIL)}&subject=${mailtoSubject}&body=${mailtoBody}`;
      const manualMailtoBtn = document.getElementById('manualMailtoBtn');
      if (manualMailtoBtn) {
        manualMailtoBtn.href = mailtoUrl;
      }

      // Configurar enlace de WhatsApp con Secretaría General
      const waText = encodeURIComponent(
        `Hola ISTAE Secretaría General, acabo de registrar mi postulación como nuevo aspirante.\n\n` +
        `📋 Mis datos son:\n` +
        `• Nombre: ${fullName}\n` +
        `• Cédula: ${cedula}\n` +
        `• Teléfono: ${phone}\n` +
        `• Correo: ${email}\n` +
        `• Carrera: ${career}\n` +
        `• Correo Institucional: ${careerEmail}\n\n` +
        `Deseo confirmar los siguientes pasos de mi proceso de admisión.`
      );
      const waBtn = document.getElementById('successWhatsAppBtn');
      if (waBtn) {
        waBtn.href = `https://wa.me/${SECRETARIA_WHATSAPP}?text=${waText}`;
      }

      // Poblar campos de resumen en el modal
      const sumFullName = document.getElementById('sumFullName');
      const sumCedula = document.getElementById('sumCedula');
      const sumPhone = document.getElementById('sumPhone');
      const sumEmail = document.getElementById('sumEmail');
      const sumCareer = document.getElementById('sumCareer');
      const sumInstEmail = document.getElementById('sumInstitutionalEmail');
      const successBadge = document.getElementById('successCareerEmailBadge');

      if (sumFullName) sumFullName.textContent = fullName;
      if (sumCedula) sumCedula.textContent = cedula;
      if (sumPhone) sumPhone.textContent = phone;
      if (sumEmail) sumEmail.textContent = email;
      if (sumCareer) sumCareer.textContent = career;
      if (sumInstEmail) sumInstEmail.textContent = careerEmail;
      if (successBadge) successBadge.textContent = careerEmail;

      // Restaurar estado del botón y mostrar mensaje de éxito
      setTimeout(() => {
        submitBtn.disabled = false;
        if (btnText) btnText.style.display = 'inline';
        if (btnLoader) btnLoader.style.display = 'none';

        form.style.display = 'none';
        success.style.display = 'block';
      }, 350);
    }

