          btn: document.getElementById('tabBtnPoa'),
          panel: document.getElementById('instPanelPoa')
        }
      };

      if (!tabs[tabKey]) return;

      // Remover activo de todos los botones y paneles
      Object.keys(tabs).forEach(k => {
        if (tabs[k].btn) tabs[k].btn.classList.remove('active');
        if (tabs[k].panel) tabs[k].panel.classList.remove('active');
      });

      // Activar la seleccionada
      if (tabs[tabKey].btn) tabs[tabKey].btn.classList.add('active');
      if (tabs[tabKey].panel) tabs[tabKey].panel.classList.add('active');

      // Scroll suave hacia la sección si se solicita
      if (shouldScroll) {
        const section = document.getElementById('gestion-transparencia');
        if (section) {
          section.scrollIntoView({
            behavior: 'smooth',
            block: 'start'
          });
        }
      }

      // Limpiar buscador al cambiar de pestaña
      clearInstSearch();
    }

    // Filtrar proyectos POA por cuatrimestre
    function filterPoaQuarter(quarter, btnElement) {
      document.querySelectorAll('.poa-quarter-btn').forEach(b => b.classList.remove('active'));
      if (btnElement) btnElement.classList.add('active');

      const cards = document.querySelectorAll('.poa-project-card');
      cards.forEach(card => {
        const cardQuarter = card.getAttribute('data-quarter');
        if (quarter === 'all' || cardQuarter === quarter) {
          card.style.display = 'flex';
        } else {
          card.style.display = 'none';
        }
      });
    }

    // Buscador interactivo en tiempo real
    function filterInstitutionalContent(query) {
      const q = query.toLowerCase().trim();
      const clearBtn = document.getElementById('instSearchClearBtn');
      const feedback = document.getElementById('instSearchFeedback');
      
      if (clearBtn) {
        clearBtn.style.display = q.length > 0 ? 'inline-block' : 'none';
      }

      const activePanel = document.querySelector('.inst-tab-panel.active');
      if (!activePanel) return;

      const items = activePanel.querySelectorAll('.searchable-inst-item');
      let visibleCount = 0;

      items.forEach(item => {
        const searchData = (item.getAttribute('data-search-content') || '').toLowerCase();
        const textData = item.textContent.toLowerCase();
        
        if (!q || searchData.includes(q) || textData.includes(q)) {
          item.style.display = '';
          visibleCount++;
        } else {
          item.style.display = 'none';
        }
      });

      if (feedback) {
        if (q.length > 0) {
          feedback.style.display = 'block';
          feedback.textContent = `Mostrando ${visibleCount} elemento(s) para "${query}" en esta sección.`;
        } else {
          feedback.style.display = 'none';
        }
      }
    }

    // Limpiar buscador interactivo
    function clearInstSearch() {
      const input = document.getElementById('instSearchInput');
      const clearBtn = document.getElementById('instSearchClearBtn');
      const feedback = document.getElementById('instSearchFeedback');

      if (input) input.value = '';
      if (clearBtn) clearBtn.style.display = 'none';
      if (feedback) feedback.style.display = 'none';

      document.querySelectorAll('.searchable-inst-item').forEach(item => {
        item.style.display = '';
      });
    }

    // Abrir modal dinámico de documentos y fichas institucionales
    function openInstDocModal(docId) {
      const data = INST_DOCS_DATA[docId];
      if (!data) return;

      currentModalDocKey = docId;

      const modal = document.getElementById('instDocModal');
      const categoryBadge = document.getElementById('instModalCategoryBadge');
      const title = document.getElementById('instModalTitle');
      const summary = document.getElementById('instModalSummaryBox');
      const unit = document.getElementById('instModalUnit');
      const status = document.getElementById('instModalStatus');
      const detailsList = document.getElementById('instModalDetailsList');
      const downloadText = document.getElementById('instModalDownloadText');

      if (categoryBadge) categoryBadge.textContent = data.category;
      if (title) title.textContent = data.title;
      if (summary) summary.textContent = data.summary;
      if (unit) unit.textContent = data.unit;
      if (status) status.textContent = data.status;
      if (downloadText) downloadText.textContent = `Descargar ${data.downloadFileName}`;

      if (detailsList) {
        detailsList.innerHTML = '';
        data.details.forEach(p => {
          const pEl = document.createElement('p');
          pEl.style.marginBottom = '6px';
          pEl.textContent = p;
          detailsList.appendChild(pEl);
        });
      }

      if (modal) {
        modal.classList.add('active');
        document.body.style.overflow = 'hidden';
      }
    }

    function closeInstDocModal() {
      const modal = document.getElementById('instDocModal');
      if (modal) {
        modal.classList.remove('active');
        document.body.style.overflow = 'auto';
      }
    }

    function handleInstModalBackdropClick(event) {
      const modal = document.getElementById('instDocModal');
      if (event.target === modal) {
        closeInstDocModal();
      }
    }

    // Descargar documento seleccionado desde el modal
    function downloadCurrentModalDoc() {
      if (currentModalDocKey && INST_DOCS_DATA[currentModalDocKey]) {
        downloadDocSimulation(INST_DOCS_DATA[currentModalDocKey].downloadFileName);
      }
    }

    // Simulación de descarga con feedback institucional
    function downloadDocSimulation(fileName) {
      // Crear un blob de texto institucional simulando el documento oficial
      const content = 
        `=======================================================================\n` +
        `INSTITUTO SUPERIOR TECNOLÓGICO ALBERTO ENRÍQUEZ (ISTAE)\n` +
        `Sede San Lorenzo - Esmeraldas, Ecuador\n` +
        `Portal Oficial: https://istae.edu.ec\n` +
        `Contacto: secretariageneralistae@gmail.com | 0996566160\n` +
        `=======================================================================\n\n` +
        `DOCUMENTO INSTITUCIONAL OFICIAL:\n` +
        `Archivo: ${fileName}\n` +
        `Fecha de Descarga: ${new Date().toLocaleString('es-EC')}\n` +
        `Aprobación: Órgano Colegiado Superior ISTAE & Normativa CPCCS / CES / CACES\n\n` +
        `Contenido certificado para fines de transparencia ciudadana y acreditación.\n` +
        `=======================================================================\n`;

      const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = fileName;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }

    // Detección de Hash en la URL para abrir pestañas directamente
    window.addEventListener('DOMContentLoaded', () => {
      const hash = window.location.hash;
      if (hash === '#planificacion-estrategica' || hash === '#gestion') {
        switchInstTab('planificacion', false);
      } else if (hash === '#transparencia-rendicion' || hash === '#transparencia') {
        switchInstTab('rendicion', false);
      } else if (hash === '#transparencia-poa' || hash === '#poa') {
        switchInstTab('poa', false);
      }
    });

    // Cerrar modal institucional con Escape
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        closeInstDocModal();
      }
    });
  </script>
</body>
</html>
